window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f0d56b42c9a9d817"]={"versions": [{"id": "FIG-f0d56b42c9a9d817", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Hardware-Ports im AUTOSAR-Metamodell der ECU-Ressourcenbeschreibung (ECU Resource Template). Es spezifiziert die statische Struktur und Zerlegung von Hardware-Elementen in Hardware-Ports und Hardware-Pins.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und zwei Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>HWElement</code> (Spezialisierung/Stereotyp <code>ARElement</code>, kursiv/abstrakt): Besitzt das Attribut <code>+ standbyCurrent: Float [0..1]</code>. Es aggregiert über die Komposition <code>+ports</code> mit der Multiplizität <code>1..*</code> ein oder mehrere <code>HWPort</code>-Elemente.\n</li><li><code>HWPort</code> (Spezialisierung/Stereotyp <code>Identifiable</code>): Repräsentiert die Port-Schnittstelle der Hardware und besitzt das Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Es aggregiert über die Komposition <code>+pins</code> mit der Multiplizität <code>*</code> null bis beliebig viele <code>HWPin</code>-Elemente.\n</li><li><code>HWPin</code> (Spezialisierung/Stereotyp <code>Identifiable</code>): Repräsentiert die physischen Pins eines Ports ohne eigene Attribute im Diagrammausschnitt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzspezifikation. Das Diagramm modelliert rein deklarative Strukturbeziehungen zur Hardware-Topologie und Parametrierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für AUTOSAR-ECU-Ressourcenbeschreibungen: Jedes <code>HWElement</code> muss mindestens einen <code>HWPort</code> besitzen (<code>1..*</code>). Ein <code>HWPort</code> muss über das Pflichtattribut <code>direction</code> mit einem der Werte <code>in</code>, <code>out</code> oder <code>inout</code> typisiert sein und kann eine beliebige Anzahl von <code>HWPin</code>-Elementen bündeln (<code>*</code>). Sowohl <code>HWPort</code> als auch <code>HWPin</code> erben von <code>Identifiable</code> und besitzen somit einen eindeutigen Bezeichner (<code>shortName</code>). <code>standbyCurrent</code> am <code>HWElement</code> ist optional (<code>[0..1]</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ae95a093e30accb7", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Hardware-Ports im AUTOSAR-Metamodell der ECU-Ressourcenbeschreibung (ECU Resource Template). Es spezifiziert die statische Struktur und Zerlegung von Hardware-Elementen in Hardware-Ports und Hardware-Pins.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und zwei Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>HWElement</code> (Spezialisierung/Stereotyp <code>ARElement</code>, kursiv/abstrakt): Besitzt das Attribut <code>+ standbyCurrent: Float [0..1]</code>. Es aggregiert über die Komposition <code>+ports</code> mit der Multiplizität <code>1..*</code> ein oder mehrere <code>HWPort</code>-Elemente.\n</li><li><code>HWPort</code> (Spezialisierung/Stereotyp <code>Identifiable</code>): Repräsentiert die Port-Schnittstelle der Hardware und besitzt das Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Es aggregiert über die Komposition <code>+pins</code> mit der Multiplizität <code>*</code> null bis beliebig viele <code>HWPin</code>-Elemente.\n</li><li><code>HWPin</code> (Spezialisierung/Stereotyp <code>Identifiable</code>): Repräsentiert die physischen Pins eines Ports ohne eigene Attribute im Diagrammausschnitt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzspezifikation. Das Diagramm modelliert rein deklarative Strukturbeziehungen zur Hardware-Topologie und Parametrierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für AUTOSAR-ECU-Ressourcenbeschreibungen: Jedes <code>HWElement</code> muss mindestens einen <code>HWPort</code> besitzen (<code>1..*</code>). Ein <code>HWPort</code> muss über das Pflichtattribut <code>direction</code> mit einem der Werte <code>in</code>, <code>out</code> oder <code>inout</code> typisiert sein und kann eine beliebige Anzahl von <code>HWPin</code>-Elementen bündeln (<code>*</code>). Sowohl <code>HWPort</code> als auch <code>HWPin</code> erben von <code>Identifiable</code> und besitzen somit einen eindeutigen Bezeichner (<code>shortName</code>). <code>standbyCurrent</code> am <code>HWElement</code> ist optional (<code>[0..1]</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f0d56b42c9a9d817", "to": "FIG-ae95a093e30accb7", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
